use fenwick::FenwickTree;

#[test]
fn test_prefix_sum_basic() {
    let mut tree = FenwickTree::new(5);
    tree.update(1, 3);
    tree.update(3, 7);
    tree.update(5, 2);
    assert_eq!(tree.prefix_sum(3), 10); // 3+0+7 = 10
    assert_eq!(tree.prefix_sum(5), 12); // 3+0+7+0+2 = 12
}

#[test]
fn test_prefix_sum_from_array() {
    let data = vec![1, 2, 3, 4, 5];
    let tree = FenwickTree::from_slice(&data);
    assert_eq!(tree.prefix_sum(1), 1);
    assert_eq!(tree.prefix_sum(3), 6); // 1+2+3
    assert_eq!(tree.prefix_sum(5), 15); // 1+2+3+4+5
}

#[test]
fn test_range_sum() {
    let data = vec![1, 2, 3, 4, 5];
    let tree = FenwickTree::from_slice(&data);
    // range_sum(l, r) = prefix_sum(r) - prefix_sum(l-1)
    assert_eq!(tree.range_sum(2, 4), 9); // 2+3+4
    assert_eq!(tree.range_sum(1, 5), 15);
}

#[test]
fn test_update_and_query() {
    let mut tree = FenwickTree::new(4);
    for i in 1..=4 {
        tree.update(i, i as i64);
    }
    assert_eq!(tree.prefix_sum(4), 10); // 1+2+3+4
    tree.update(2, 5); // add 5 to position 2
    assert_eq!(tree.prefix_sum(4), 15);
}

#[test]
fn test_single_element() {
    let mut tree = FenwickTree::new(1);
    tree.update(1, 42);
    assert_eq!(tree.prefix_sum(1), 42);
}

